<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { HardDriveDownload, LogOut, Plus, Trash2 } from '@lucide/vue'
import { api, json } from '../api'
import { useAuthStore } from '../stores/auth'
import type { Preferences, User } from '../types'

const props=defineProps<{modelValue:boolean;preferences:Preferences}>()
const emit=defineEmits<{'update:modelValue':[boolean];preferences:[Preferences];logout:[]}>()
const auth=useAuthStore();const tab=ref('terminal');const users=ref<User[]>([]);const devices=ref<any[]>([]);const audits=ref<any[]>([]);const stats=ref<any>({});const newUser=ref({username:'',password:'',role:'user'});const passwordForm=ref({currentPassword:'',newPassword:'',confirmPassword:''})
async function load(){devices.value=await api('/api/auth/devices');audits.value=await api('/api/audit');if(auth.user?.role==='admin'){users.value=await api('/api/admin/users');stats.value=await api('/api/admin/stats')}}
onMounted(load)
async function savePreferences(){await api('/api/preferences',{method:'PUT',body:json(props.preferences)});emit('preferences',{...props.preferences});ElMessage.success('设置已保存')}
async function revoke(id:string){await api(`/api/auth/devices/${id}`,{method:'DELETE'});devices.value=devices.value.filter(v=>v.id!==id)}
async function createUser(){try{const u=await api<User>('/api/admin/users',{method:'POST',body:json(newUser.value)});users.value.push(u);newUser.value={username:'',password:'',role:'user'};ElMessage.success('用户已创建')}catch(e){ElMessage.error(e instanceof Error?e.message:'创建失败')}}
async function toggleUser(user:User){const disabled=!user.disabled;await api(`/api/admin/users/${user.id}`,{method:'PATCH',body:json({disabled})});user.disabled=disabled}
async function backup(){const result=await api<{file:string}>('/api/admin/backup',{method:'POST'});ElMessage.success(`备份已创建：${result.file}`)}
async function changePassword(){const p=passwordForm.value;if(p.newPassword!==p.confirmPassword)return ElMessage.warning('两次输入的新密码不一致');try{await api('/api/auth/password',{method:'POST',body:json({currentPassword:p.currentPassword,newPassword:p.newPassword})});passwordForm.value={currentPassword:'',newPassword:'',confirmPassword:''};ElMessage.success('密码已修改')}catch(e){ElMessage.error(e instanceof Error?e.message:'修改失败')}}
async function logout(){try{await ElMessageBox.confirm('退出账号不会终止远程 tmux 任务。','退出登录',{confirmButtonText:'退出',cancelButtonText:'取消'});emit('logout')}catch{}}
</script>
<template><el-drawer :model-value="modelValue" title="设置" size="min(720px, 100vw)" @open="load" @update:model-value="emit('update:modelValue',$event)"><el-tabs v-model="tab" class="settings-tabs"><el-tab-pane label="终端" name="terminal"><div class="settings-section"><h3>终端外观</h3><div class="setting-row"><span>字号</span><el-slider v-model="preferences.fontSize" :min="10" :max="24" show-input /></div><div class="setting-row"><span>行高</span><el-slider v-model="preferences.lineHeight" :min="1" :max="2" :step="0.1" show-input /></div><div class="setting-row"><span>光标</span><el-select v-model="preferences.cursorStyle"><el-option label="方块" value="block"/><el-option label="竖线" value="bar"/><el-option label="下划线" value="underline"/></el-select></div><div class="setting-row"><span>光标闪烁</span><el-switch v-model="preferences.cursorBlink"/></div><div class="setting-row"><span>多行粘贴保护</span><el-switch v-model="preferences.pasteGuard"/></div><el-button type="primary" @click="savePreferences">保存设置</el-button></div><div class="settings-section"><h3>修改登录密码</h3><div class="inline-form password-form"><el-input v-model="passwordForm.currentPassword" type="password" show-password placeholder="当前密码"/><el-input v-model="passwordForm.newPassword" type="password" show-password placeholder="新密码，至少 10 位"/><el-input v-model="passwordForm.confirmPassword" type="password" show-password placeholder="确认新密码"/><el-button @click="changePassword">修改</el-button></div></div></el-tab-pane><el-tab-pane label="登录设备" name="devices"><div class="list-stack"><div v-for="d in devices" :key="d.id" class="data-row"><div><strong>{{ d.user_agent || '未知设备' }}</strong><small>{{ d.ip }} · {{ new Date(d.last_seen_at).toLocaleString() }}</small></div><el-button :icon="Trash2" text @click="revoke(d.id)">撤销</el-button></div></div></el-tab-pane><el-tab-pane label="审计" name="audit"><div class="list-stack"><div v-for="a in audits" :key="a.id" class="data-row"><div><strong>{{ a.event_type }}</strong><small>{{ a.resource_type }} {{ a.resource_id }} · {{ new Date(a.created_at).toLocaleString() }}</small></div><span class="muted">{{ a.ip }}</span></div></div></el-tab-pane><el-tab-pane v-if="auth.user?.role==='admin'" label="管理" name="admin"><div class="stats-grid"><div><strong>{{stats.users||0}}</strong><span>用户</span></div><div><strong>{{stats.hosts||0}}</strong><span>主机</span></div><div><strong>{{stats.sessions||0}}</strong><span>活动会话</span></div></div><div class="settings-section"><h3>创建用户</h3><div class="inline-form"><el-input v-model="newUser.username" placeholder="用户名"/><el-input v-model="newUser.password" type="password" show-password placeholder="至少 10 位密码"/><el-select v-model="newUser.role"><el-option label="普通用户" value="user"/><el-option label="管理员" value="admin"/></el-select><el-button :icon="Plus" type="primary" @click="createUser">创建</el-button></div></div><div class="list-stack"><div v-for="u in users" :key="u.id" class="data-row"><div><strong>{{u.username}}</strong><small>{{u.role==='admin'?'管理员':'普通用户'}}</small></div><el-switch :model-value="!u.disabled" :disabled="u.id===auth.user?.id" active-text="启用" @change="toggleUser(u)"/></div></div><el-button :icon="HardDriveDownload" @click="backup">创建数据库备份</el-button></el-tab-pane></el-tabs><template #footer><el-button :icon="LogOut" @click="logout">退出登录</el-button></template></el-drawer></template>
